INSERT INTO public.quizzes (id, subject, unit, title, description) VALUES ('62ce47c0-16fa-4c41-8dfc-5f5f4f9cf541'::uuid, 'Economics', 'Unit 1', 'Molarum Grade 10 — Economics Unit 1: Theory of Consumer Behaviour', 'Source-grounded Molarum Grade 10 Economics questions for Unit 1: Theory of Consumer Behaviour.') ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, unit = EXCLUDED.unit, title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('d4dda957-f0c5-4f32-8b80-d951b1fa8c64'::uuid, '62ce47c0-16fa-4c41-8dfc-5f5f4f9cf541'::uuid, 'multiple_choice', 'According to the unit introduction, who is a consumer?', 'A decision-making unit (an individual or a household) who uses or consumes a commodity or service', 'The excerpt defines a consumer as a decision-making unit—an individual or household—who uses or consumes a commodity or service.', 0),('743ed7e6-e676-4b42-85fb-b48523c8058e'::uuid, '62ce47c0-16fa-4c41-8dfc-5f5f4f9cf541'::uuid, 'multiple_choice', 'What is the main concern of the theory of consumer behaviour as stated in the unit?', 'How consumers decide on the basket of goods and services to maximize satisfaction', 'The excerpt states the theory is concerned with how a consumer decides on a basket of goods and services to maximize his/her satisfaction.', 1),('baabfae2-8115-480e-8c58-f6a1081d0ae5'::uuid, '62ce47c0-16fa-4c41-8dfc-5f5f4f9cf541'::uuid, 'multiple_choice', 'Which of the following is listed as an assumption of the theory of consumer behaviour in this unit?', 'The consumer has a limited income', 'The excerpt lists as an important assumption that the consumer has a limited income.', 2),('47c450e0-efcd-4d0e-8fd0-726a5adebfeb'::uuid, '62ce47c0-16fa-4c41-8dfc-5f5f4f9cf541'::uuid, 'multiple_choice', 'Which of the following is NOT listed as a learning objective for this unit?', 'Explain the determination of national income by fiscal policy', 'The unit objectives list cardinal utility, the law of diminishing marginal utility, and consumer optimum under cardinal approaches; fiscal policy and national income determination are not listed in this unit''s objectives.', 3),('6a8eda85-d5b7-49d6-8948-75c3d74055e7'::uuid, '62ce47c0-16fa-4c41-8dfc-5f5f4f9cf541'::uuid, 'multiple_choice', 'How does the text define ''utility''?', 'The level of satisfaction or pleasure derived from the consumption of a good or service', 'The excerpt defines utility as the level of satisfaction or pleasure derived from consuming a good or service, or the power of a commodity to satisfy human wants.', 4),('7bf9cf82-168e-4f54-89db-1c7ca4a9f62c'::uuid, '62ce47c0-16fa-4c41-8dfc-5f5f4f9cf541'::uuid, 'multiple_choice', 'Which statement illustrates the relativity of utility as explained in the unit?', 'The same commodity can provide different utilities to different consumers', 'The excerpt explains that utility is subjective and not absolute, so the same commodity provides different utilities to different consumers.', 5),('16114c86-c52f-41c2-846a-ed2a8f9333e1'::uuid, '62ce47c0-16fa-4c41-8dfc-5f5f4f9cf541'::uuid, 'multiple_choice', 'Which feature is specific to the cardinal utility approach according to the text?', 'Utility is measurable and can be expressed in numbers or money (utils)', 'The excerpt states that cardinal utility treats utility as measurable, expressible in numbers or monetary units called ''utils''.', 6),('93b96901-7271-425c-8c23-2b5b3e1dbe40'::uuid, '62ce47c0-16fa-4c41-8dfc-5f5f4f9cf541'::uuid, 'multiple_choice', 'What does Total Utility (TU) refer to in the unit''s explanation?', 'The total amount of satisfaction a consumer gets from consuming specific quantities of a commodity', 'The excerpt defines total utility as the total amount of satisfaction derived from consuming specific quantities of a commodity.', 7),('30a0bfc1-bcc5-47db-813d-63d9ee0b79ed'::uuid, '62ce47c0-16fa-4c41-8dfc-5f5f4f9cf541'::uuid, 'multiple_choice', 'Which formula correctly gives marginal utility (MU) as presented in the excerpt?', 'MU = ΔTU / ΔQ', 'The excerpt provides the marginal utility formula as the change in total utility divided by the change in quantity: MU = ΔTU / ΔQ.', 8),('259a0f07-1014-4e1a-8049-d18f2a1dec8b'::uuid, '62ce47c0-16fa-4c41-8dfc-5f5f4f9cf541'::uuid, 'multiple_choice', 'In the Beka orange example, total utility rises from 10 utils at 2 oranges to 12 utils at 3 oranges. What is the marginal utility of the 3rd orange?', '2 utils', 'The excerpt computes MU as the change in total utility (12 − 10) divided by the change in quantity (1), giving 2 utils for the 3rd orange.', 9),('6eaa4d5e-d100-4d99-8ca9-df41c2d6eb5e'::uuid, '62ce47c0-16fa-4c41-8dfc-5f5f4f9cf541'::uuid, 'multiple_choice', 'Table 1.2 (banana) shows total utility reaches its maximum (saturation) point at which quantity?', '7', 'The excerpt states total utility reaches its highest satisfaction of 37 utils at 7 quantities, making 7 the saturation point.', 10),('a639ec1a-0272-4fe0-8453-7e79817f9307'::uuid, '62ce47c0-16fa-4c41-8dfc-5f5f4f9cf541'::uuid, 'multiple_choice', 'Which statement best summarizes the law of diminishing marginal utility as given in the unit?', 'As quantity consumed increases, the additional utility from successive units decreases (other goods constant)', 'The excerpt states the law as marginal utility decreasing with successive units consumed, ceteris paribus.', 11),('f4c59560-8bf2-4c50-8bfa-9ef6dc7858a5'::uuid, '62ce47c0-16fa-4c41-8dfc-5f5f4f9cf541'::uuid, 'multiple_choice', 'Under the cardinal approach for a single commodity X, when is the consumer in equilibrium?', 'When MUx = Px', 'The excerpt gives the condition for single-commodity equilibrium as marginal utility of X equaling its market price: MUx = Px.', 12),('62ce43d8-1957-4cee-8399-4560a63c2de5'::uuid, '62ce47c0-16fa-4c41-8dfc-5f5f4f9cf541'::uuid, 'multiple_choice', 'If for a commodity X the marginal utility MUx is greater than the price Px, what does the unit state the consumer should do to increase welfare?', 'Purchase more units of X', 'The excerpt explains that if MUx > Px the consumer can increase welfare by buying more units of the commodity.', 13),('04a7b16a-589c-45af-89b4-2e1bc4574c2b'::uuid, '62ce47c0-16fa-4c41-8dfc-5f5f4f9cf541'::uuid, 'multiple_choice', 'In the single-commodity case described, what equation represents the consumer''s expenditure on that commodity when spending all income on it?', 'Px × Qx = Consumer''s Income', 'The excerpt states that expenditure on a single commodity is Px Qx, which equals the consumer''s budget when all income is spent on that commodity.', 14),('c75be3e1-0ec0-4c61-82e5-fe3e5f6d712e'::uuid, '62ce47c0-16fa-4c41-8dfc-5f5f4f9cf541'::uuid, 'multiple_choice', 'What is the condition for consumer equilibrium when consuming more than one commodity according to the excerpt?', 'MU_A / P_A = MU_B / P_B = ... = MU_N / P_N', 'The excerpt states that utility is maximized when the ratios of marginal utilities to prices are equal across all commodities.', 15),('375cbe4e-b191-445e-8f07-a4d1481340f8'::uuid, '62ce47c0-16fa-4c41-8dfc-5f5f4f9cf541'::uuid, 'multiple_choice', 'Using Table 1.4 (bread, price = Birr 2), at which quantity of bread does the consumer reach equilibrium?', '2 quantities', 'The worked example shows equilibrium occurs at 2 quantities since MUbread / Pbread = 2 / 2 = 1, equalling the marginal utility of money.', 16),('4ee1cbbc-9001-48bb-80e5-2ed33e829768'::uuid, '62ce47c0-16fa-4c41-8dfc-5f5f4f9cf541'::uuid, 'multiple_choice', 'In the example with bread (Px = Birr 2) and injera (Py = Birr 4) and income Birr 22 (Table 1.5), which combination maximizes the consumer''s utility?', '3 units of bread and 4 units of injera', 'The solution given in the excerpt finds equilibrium at 3 units of X (bread) and 4 units of Y (injera), satisfying MUx/Px = MUy/Py and the budget constraint 2(3)+4(4)=22.', 17),('61b2edee-4341-4b45-8af0-2be416996172'::uuid, '62ce47c0-16fa-4c41-8dfc-5f5f4f9cf541'::uuid, 'multiple_choice', 'In the Table 1.5 example, how does the excerpt show total expenditure equals income for the equilibrium bundle?', 'By calculating 2(3) + 4(4) = 22', 'The excerpt verifies the budget equation by calculating expenditure 2×3 + 4×4 = 22, which equals the consumer''s income of 22 Birr.', 18),('bcdc1a4b-ed5f-4fed-8c7d-a98e1e44a94f'::uuid, '62ce47c0-16fa-4c41-8dfc-5f5f4f9cf541'::uuid, 'multiple_choice', 'Which of the following is an assumption of the ordinal utility approach listed in the unit?', 'Consumers can rank baskets of goods in order of preference (utility is ordinal)', 'The excerpt states ordinal utility assumes utility is ordinal and consumers can rank consumption bundles by preference.', 19),('4e425a9d-e67d-4be1-829f-84e3b609c26c'::uuid, '62ce47c0-16fa-4c41-8dfc-5f5f4f9cf541'::uuid, 'true_false', 'Total utility is the sum of all marginal utilities.', 'True', 'The relationship between total and marginal utility in the excerpt implies total utility is the accumulation (sum) of marginal utilities derived from each unit.', 20),('2cadeec2-0e14-40be-8e07-cf4f19909fcd'::uuid, '62ce47c0-16fa-4c41-8dfc-5f5f4f9cf541'::uuid, 'true_false', 'Total utility increases as long as marginal utility is positive.', 'True', 'The excerpt explains total utility rises with consumption while marginal utility remains positive and stops increasing once marginal utility becomes zero or negative.', 21),('c664f17b-89ae-4b51-8a40-c768fb6d9f24'::uuid, '62ce47c0-16fa-4c41-8dfc-5f5f4f9cf541'::uuid, 'true_false', 'The law of diminishing marginal utility is an assumption of ordinal utility theory.', 'False', 'The excerpt presents the law of diminishing marginal utility as central to the cardinal approach, whereas ordinal utility assumptions include the diminishing marginal rate of substitution, not LDMU.', 22),('fd01a2a8-5886-459c-802a-7ea365e752d2'::uuid, '62ce47c0-16fa-4c41-8dfc-5f5f4f9cf541'::uuid, 'true_false', 'Under ordinal utility, the level of satisfaction obtained from commodities can be measured in monetary units.', 'False', 'The excerpt explains ordinal utility cannot be measured absolutely or in monetary units; it only ranks bundles by preference.', 23),('ee310072-4c71-495e-8bb6-d361f5d29550'::uuid, '62ce47c0-16fa-4c41-8dfc-5f5f4f9cf541'::uuid, 'fill_blank', 'Define ''utility'' as presented in the unit.', 'Utility is the level of satisfaction or pleasure derived from the consumption of a good or service.', 'The excerpt defines utility as the level of satisfaction or pleasure from consuming a good or service, and as the power of a commodity to satisfy human wants.', 24),('1bc718da-7d39-439c-8aed-c742b6395cb4'::uuid, '62ce47c0-16fa-4c41-8dfc-5f5f4f9cf541'::uuid, 'fill_blank', 'Explain the ''relativity of utility'' in one sentence based on the unit.', 'Relativity of utility means utility is subjective and varies by person, place, and time, so the same commodity can give different utilities to different consumers.', 'The excerpt states utility is subjective to a person''s needs and can differ across individuals, places, and times—for example, jackets give different utility in cold versus hot seasons.', 25),('02e42ae4-b424-4669-8766-a38b2ccbce9c'::uuid, '62ce47c0-16fa-4c41-8dfc-5f5f4f9cf541'::uuid, 'fill_blank', 'List three assumptions of the cardinal utility theory mentioned in the unit.', 'The consumer is rational; utility is cardinal (measurable in numbers or money); and the law of diminishing marginal utility holds.', 'The excerpt lists several cardinal assumptions including rationality, that utility is cardinally measurable, and diminishing marginal utility among others.', 26),('874809be-c80b-4e5b-8518-077860b88bab'::uuid, '62ce47c0-16fa-4c41-8dfc-5f5f4f9cf541'::uuid, 'fill_blank', 'Write the formula for marginal utility given in the unit.', 'MU = ΔTU / ΔQ', 'The excerpt defines marginal utility as the change in total utility divided by the change in quantity, MU = ΔTU/ΔQ.', 27),('181a6327-97dc-430b-8578-10366a1ed07c'::uuid, '62ce47c0-16fa-4c41-8dfc-5f5f4f9cf541'::uuid, 'fill_blank', 'State the law of diminishing marginal utility in one sentence as in the unit.', 'As the quantity consumed of a commodity increases over a period of time (holding other goods constant), the marginal utility derived from successive units decreases.', 'The excerpt states LDMU as marginal utility diminishing as consumption of a commodity increases, ceteris paribus.', 28),('09979801-9692-40e1-81ab-6b42868a4a84'::uuid, '62ce47c0-16fa-4c41-8dfc-5f5f4f9cf541'::uuid, 'fill_blank', 'Define consumer equilibrium in the case of a single commodity as presented in the unit.', 'Consumer equilibrium occurs when the marginal utility of the commodity equals its market price (MUx = Px).', 'The excerpt explains that for one commodity the consumer is in equilibrium when MUx equals the price Px, as further purchases would not increase welfare.', 29),('ace30180-ebc9-4c7d-8b85-ba05a4eafcde'::uuid, '62ce47c0-16fa-4c41-8dfc-5f5f4f9cf541'::uuid, 'fill_blank', 'Give three assumptions of the ordinal utility theory as listed in the unit.', 'Rationality of the consumer; utility is ordinal (can be ranked but not measured numerically); and consistency and transitivity of choices.', 'The excerpt lists ordinal assumptions including rational consumers, ordinal measurement of utility, and consistency/transitivity of choices among others.', 30),('df053dae-0623-455c-8970-8b0f620acd84'::uuid, '62ce47c0-16fa-4c41-8dfc-5f5f4f9cf541'::uuid, 'fill_blank', 'Briefly explain the marginal rate of substitution and the diminishing marginal rate of substitution as in the unit.', 'The marginal rate of substitution is the rate at which a consumer will substitute one good for another while keeping satisfaction constant, and the diminishing marginal rate of substitution means this willingness to substitute falls as the consumer has more of the substituted good.', 'The excerpt defines MRS as the rate of substitution keeping utility unchanged and states it diminishes as one consumes more of one good, so fewer units of the other are given up for additional units.', 31),('bc42b51f-2307-4345-844a-7148135557d7'::uuid, '62ce47c0-16fa-4c41-8dfc-5f5f4f9cf541'::uuid, 'fill_blank', 'Using Table 1.2 (banana), what is the marginal utility at quantity 3?', '7 utils', 'Table 1.2 shows MU at Q=3 equals 7 utils as listed in the marginal utility row for bananas.', 32),('11c7bbcd-4c42-440a-859e-800df7f306d5'::uuid, '62ce47c0-16fa-4c41-8dfc-5f5f4f9cf541'::uuid, 'fill_blank', 'From Table 1.2 (banana), what is the total utility at quantity 7?', '37 utils', 'The excerpt states the total utility at 7 units of banana is 37 utils, the highest (saturation) point in Table 1.2.', 33),('045421b5-fb4a-482f-8beb-53aa08f92105'::uuid, '62ce47c0-16fa-4c41-8dfc-5f5f4f9cf541'::uuid, 'fill_blank', 'Using Table 1.2 (banana), what is the marginal utility at quantity 9?', '-2 utils', 'Table 1.2 lists MU at Q=9 as −2 utils in the marginal utility row for bananas.', 34),('2ccdba1e-57f0-4c62-8923-f549550b1070'::uuid, '62ce47c0-16fa-4c41-8dfc-5f5f4f9cf541'::uuid, 'fill_blank', 'From Table 1.3 for commodity Y, what is the marginal utility at quantity 5?', '0 utils', 'Table 1.3 shows TU for Y at Q=5 equals 22 and at Q=4 equals 22, so MU at Q=5 is 22−22 = 0 utils.', 35),('48ea68ca-c8c9-47c6-820a-89d08f0e9b28'::uuid, '62ce47c0-16fa-4c41-8dfc-5f5f4f9cf541'::uuid, 'fill_blank', 'Using Table 1.5 and the solution shown, what is the maximum total utility obtained at the equilibrium bundle?', '40 utils', 'The excerpt calculates maximum total utility at equilibrium by summing MU contributions for bread and injera to get TU = 40 utils.', 36),('aab68be1-6c38-47e0-8f52-a2b5e85ffe46'::uuid, '62ce47c0-16fa-4c41-8dfc-5f5f4f9cf541'::uuid, 'fill_blank', 'From Table 1.5, how many units of bread (X) and injera (Y) should the individual purchase to maximize utility given income Birr 22 and prices Px=2, Py=4?', '3 units of bread and 4 units of injera', 'The excerpt''s solution shows the consumer is in equilibrium consuming 3 units of X and 4 units of Y, satisfying MU/P equality and the budget 2×3 + 4×4 = 22.', 37),('fabcd90d-51ac-4238-8654-e52dfecdd62b'::uuid, '62ce47c0-16fa-4c41-8dfc-5f5f4f9cf541'::uuid, 'fill_blank', 'According to Table 1.2, by how many utils does total utility decrease when moving from 8 units to 10 units of banana?', '7 utils', 'Table 1.2 lists TU at Q=8 as 37 utils and at Q=10 as 30 utils, so total utility falls by 37 − 30 = 7 utils.', 38),('6227f29d-c13a-4df8-8c0f-648b96eab18a'::uuid, '62ce47c0-16fa-4c41-8dfc-5f5f4f9cf541'::uuid, 'fill_blank', 'Using Table 1.4 (bread with price = Birr 2), what is the marginal utility per Birr at quantity 3?', '0.5', 'Table 1.4 shows MU at Q=3 equals 1 utils and with price 2 Birr the MU per Birr is 1 ÷ 2 = 0.5 as listed.', 39) ON CONFLICT (id) DO UPDATE SET quiz_id = EXCLUDED.quiz_id, question_type = EXCLUDED.question_type, question_text = EXCLUDED.question_text, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, order_index = EXCLUDED.order_index;
